    const nvidiaName = nvidia?.[0]?.name
    return adapters.find(name => name !== nvidiaName) ?? adapters[0] ?? null
  }

  function tick() {
    const cpu = cpuPercent()
    const memPct = (1 - os.freemem() / os.totalmem()) * 100
    push(history.cpu, cpu)
